
-- reset old quiz data
DELETE FROM public.quiz_answers;
DELETE FROM public.quiz_attempts;
DELETE FROM public.student_progress;
DELETE FROM public.questions;
DELETE FROM public.levels;

-- insert the 5 Law of Sines levels
INSERT INTO public.levels (level_number, title, description, is_active)
VALUES
  (1, 'Figures', 'Identify information from Law of Sines triangle figures.', true),
  (2, 'Find AC', 'Practice finding missing sides and especially side AC.', true),
  (3, 'Words', 'Use the Law of Sines to interpret and reason through word problems.', true),
  (4, 'Figure Out / Illustration', 'Read diagrams and solve for the missing measurement.', true),
  (5, 'Problem Solving', 'Apply the Law of Sines to realistic triangle problems.', true)
ON CONFLICT (level_number) DO UPDATE
SET title = EXCLUDED.title,
    description = EXCLUDED.description,
    is_active = EXCLUDED.is_active;

-- insert the 150 Law of Sines questions
